//! Field by field, a `Mob` against its ECS cow (generated by `gen/groups.py`); the test's oracle.
use super::view::CowItem;
use crate::mobs::Mob;

fn d(out: &mut Vec<String>, name: &str, a: String, b: String) {
    if a != b {
        out.push(format!("{name}: {a} / {b}"));
    }
}
/// The fields that differ, as `name: mob / cow`.
pub fn differences(m: &Mob, c: &CowItem<'_, '_>) -> Vec<String> {
    let mut out = Vec::new();
    d(&mut out, "id", format!("{:?}", m.id), format!("{:?}", c.id.id));
    d(&mut out, "kind", format!("{:?}", m.kind), format!("{:?}", c.id.kind));
    d(&mut out, "position", format!("{:?}", m.position), format!("{:?}", c.motion.position));
    d(&mut out, "previous", format!("{:?}", m.previous), format!("{:?}", c.motion.previous));
    d(&mut out, "velocity", format!("{:?}", m.velocity), format!("{:?}", c.motion.velocity));
    d(&mut out, "yaw", format!("{:?}", m.yaw), format!("{:?}", c.motion.yaw));
    d(&mut out, "previous_yaw", format!("{:?}", m.previous_yaw), format!("{:?}", c.motion.previous_yaw));
    d(&mut out, "body_yaw", format!("{:?}", m.body_yaw), format!("{:?}", c.motion.body_yaw));
    d(&mut out, "previous_body_yaw", format!("{:?}", m.previous_body_yaw), format!("{:?}", c.motion.previous_body_yaw));
    d(&mut out, "head_yaw", format!("{:?}", m.head_yaw), format!("{:?}", c.motion.head_yaw));
    d(&mut out, "previous_head_yaw", format!("{:?}", m.previous_head_yaw), format!("{:?}", c.motion.previous_head_yaw));
    d(&mut out, "head_pitch", format!("{:?}", m.head_pitch), format!("{:?}", c.motion.head_pitch));
    d(&mut out, "previous_head_pitch", format!("{:?}", m.previous_head_pitch), format!("{:?}", c.motion.previous_head_pitch));
    d(&mut out, "on_ground", format!("{:?}", m.on_ground), format!("{:?}", c.motion.on_ground));
    d(&mut out, "horizontal_collision", format!("{:?}", m.horizontal_collision), format!("{:?}", c.motion.horizontal_collision));
    d(&mut out, "vertical_collision_below", format!("{:?}", m.vertical_collision_below), format!("{:?}", c.motion.vertical_collision_below));
    d(&mut out, "needs_sync", format!("{:?}", m.needs_sync), format!("{:?}", c.motion.needs_sync));
    d(&mut out, "sync_position", format!("{:?}", m.sync_position), format!("{:?}", c.motion.sync_position));
    d(&mut out, "fall_distance", format!("{:?}", m.fall_distance), format!("{:?}", c.motion.fall_distance));
    d(&mut out, "stuck_multiplier", format!("{:?}", m.stuck_multiplier), format!("{:?}", c.motion.stuck_multiplier));
    d(&mut out, "piston", format!("{:?}", m.piston), format!("{:?}", c.motion.piston));
    d(&mut out, "supporting", format!("{:?}", m.supporting), format!("{:?}", c.motion.supporting));
    d(&mut out, "climbing", format!("{:?}", m.climbing), format!("{:?}", c.motion.climbing));
    d(&mut out, "on_climbable", format!("{:?}", m.on_climbable), format!("{:?}", c.motion.on_climbable));
    d(&mut out, "no_gravity", format!("{:?}", m.no_gravity), format!("{:?}", c.motion.no_gravity));
    d(&mut out, "no_physics", format!("{:?}", m.no_physics), format!("{:?}", c.motion.no_physics));
    d(&mut out, "pushed", format!("{:?}", m.pushed), format!("{:?}", c.motion.pushed));
    d(&mut out, "limb_position", format!("{:?}", m.limb_position), format!("{:?}", c.motion.limb_position));
    d(&mut out, "limb_speed", format!("{:?}", m.limb_speed), format!("{:?}", c.motion.limb_speed));
    d(&mut out, "previous_limb_speed", format!("{:?}", m.previous_limb_speed), format!("{:?}", c.motion.previous_limb_speed));
    d(&mut out, "health", format!("{:?}", m.health), format!("{:?}", c.vitals.health));
    d(&mut out, "hurt_time", format!("{:?}", m.hurt_time), format!("{:?}", c.vitals.hurt_time));
    d(&mut out, "invulnerable", format!("{:?}", m.invulnerable), format!("{:?}", c.vitals.invulnerable));
    d(&mut out, "invulnerable_time", format!("{:?}", m.invulnerable_time), format!("{:?}", c.vitals.invulnerable_time));
    d(&mut out, "death_time", format!("{:?}", m.death_time), format!("{:?}", c.vitals.death_time));
    d(&mut out, "impulse_grace_time", format!("{:?}", m.impulse_grace_time), format!("{:?}", c.vitals.impulse_grace_time));
    d(&mut out, "absorption", format!("{:?}", m.absorption), format!("{:?}", c.vitals.absorption));
    d(&mut out, "last_hurt", format!("{:?}", m.last_hurt), format!("{:?}", c.vitals.last_hurt));
    d(&mut out, "dealt_absorbed", format!("{:?}", m.dealt_absorbed), format!("{:?}", c.vitals.dealt_absorbed));
    d(&mut out, "last_damage", format!("{:?}", m.last_damage), format!("{:?}", c.vitals.last_damage));
    d(&mut out, "accepted_hit", format!("{:?}", m.accepted_hit), format!("{:?}", c.vitals.accepted_hit));
    d(&mut out, "death_canceled", format!("{:?}", m.death_canceled), format!("{:?}", c.vitals.death_canceled));
    d(&mut out, "last_direct", format!("{:?}", m.last_direct), format!("{:?}", c.vitals.last_direct));
    d(&mut out, "attacker_aim", format!("{:?}", m.attacker_aim), format!("{:?}", c.vitals.attacker_aim));
    d(&mut out, "creative_attacker", format!("{:?}", m.creative_attacker), format!("{:?}", c.vitals.creative_attacker));
    d(&mut out, "projectile_motion", format!("{:?}", m.projectile_motion), format!("{:?}", c.vitals.projectile_motion));
    d(&mut out, "invulnerable_flag", format!("{:?}", m.invulnerable_flag), format!("{:?}", c.vitals.invulnerable_flag));
    d(&mut out, "combat", format!("{:?}", m.combat), format!("{:?}", c.vitals.combat));
    d(&mut out, "removed", format!("{:?}", m.removed), format!("{:?}", c.vitals.removed));
    d(&mut out, "despawn", format!("{:?}", m.despawn), format!("{:?}", c.vitals.despawn));
    d(&mut out, "gear_knockback_resistance", format!("{:?}", m.gear_knockback_resistance), format!("{:?}", c.vitals.gear_knockback_resistance));
    d(&mut out, "fire_ticks", format!("{:?}", m.fire_ticks), format!("{:?}", c.env.fire_ticks));
    d(&mut out, "ticks_frozen", format!("{:?}", m.ticks_frozen), format!("{:?}", c.env.ticks_frozen));
    d(&mut out, "in_powder_snow", format!("{:?}", m.in_powder_snow), format!("{:?}", c.env.in_powder_snow));
    d(&mut out, "air", format!("{:?}", m.air), format!("{:?}", c.env.air));
    d(&mut out, "first_tick", format!("{:?}", m.first_tick), format!("{:?}", c.env.first_tick));
    d(&mut out, "was_eye_in_water", format!("{:?}", m.was_eye_in_water), format!("{:?}", c.env.was_eye_in_water));
    d(&mut out, "age", format!("{:?}", m.age), format!("{:?}", c.clk.age));
    d(&mut out, "ambient_timer", format!("{:?}", m.ambient_timer), format!("{:?}", c.clk.ambient_timer));
    d(&mut out, "persistent", format!("{:?}", m.persistent), format!("{:?}", c.clk.persistent));
    d(&mut out, "no_ai", format!("{:?}", m.no_ai), format!("{:?}", c.clk.no_ai));
    d(&mut out, "silent", format!("{:?}", m.silent), format!("{:?}", c.clk.silent));
    d(&mut out, "swell", format!("{:?}", m.swell), format!("{:?}", c.clk.swell));
    d(&mut out, "previous_swell", format!("{:?}", m.previous_swell), format!("{:?}", c.clk.previous_swell));
    d(&mut out, "max_swell", format!("{:?}", m.max_swell), format!("{:?}", c.clk.max_swell));
    d(&mut out, "fluids", format!("{:?}", m.fluids), format!("{:?}", c.fluids.0));
    d(&mut out, "attrs", format!("{:?}", m.attrs), format!("{:?}", c.attrs.0));
    d(&mut out, "anim", format!("{:?}", m.anim), format!("{:?}", c.anim.0));
    out
}
